def _resample_nearest_jit(src, row_coords, col_coords, nodata):
    """Nearest-neighbor resampling with NaN propagation."""
    h_out, w_out = row_coords.shape
    sh, sw = src.shape
    out = np.empty((h_out, w_out), dtype=np.float64)
    for i in range(h_out):
        for j in range(w_out):
            r = row_coords[i, j]
            c = col_coords[i, j]
            if _outside_footprint(r, c, sh, sw):
                out[i, j] = nodata
                continue
            ri = int(r + 0.5)
            ci = int(c + 0.5)
            if ri < 0:
                ri = 0
            if ri >= sh:
                ri = sh - 1
            if ci < 0:
                ci = 0
            if ci >= sw:
                ci = sw - 1
            v = src[ri, ci]
            # NaN check: works for float64
            if v != v:
                out[i, j] = nodata
            else:
                out[i, j] = v
    return out


@njit(nogil=True, cache=True)
def _resample_cubic_jit(src, row_coords, col_coords, nodata):
    """Catmull-Rom cubic resampling with NaN-aware fallback to bilinear.

    Separable: interpolate 4 row-slices along columns, then combine
    along rows.  When any of the 16 neighbors is NaN, falls back to
    bilinear with weight renormalization (matching GDAL behavior).
    """
    h_out, w_out = row_coords.shape
    sh, sw = src.shape
    out = np.empty((h_out, w_out), dtype=np.float64)
    for i in range(h_out):
        for j in range(w_out):
            r = row_coords[i, j]
            c = col_coords[i, j]
            if _outside_footprint(r, c, sh, sw):
                out[i, j] = nodata
                continue

            r0 = int(np.floor(r))
            c0 = int(np.floor(c))
            fr = r - r0
            fc = c - c0

            # Catmull-Rom column weights (a = -0.5)
            fc2 = fc * fc
            fc3 = fc2 * fc
            wc0 = -0.5 * fc3 + fc2 - 0.5 * fc
            wc1 = 1.5 * fc3 - 2.5 * fc2 + 1.0
            wc2 = -1.5 * fc3 + 2.0 * fc2 + 0.5 * fc
            wc3 = 0.5 * fc3 - 0.5 * fc2

            # Catmull-Rom row weights
            fr2 = fr * fr
            fr3 = fr2 * fr
            wr0 = -0.5 * fr3 + fr2 - 0.5 * fr
            wr1 = 1.5 * fr3 - 2.5 * fr2 + 1.0
            wr2 = -1.5 * fr3 + 2.0 * fr2 + 0.5 * fr
            wr3 = 0.5 * fr3 - 0.5 * fr2

            val = 0.0
            has_nan = False
            for di in range(4):
                ri = r0 - 1 + di
                ric = ri
                if ric < 0:
                    ric = 0
                elif ric >= sh:
                    ric = sh - 1
                # Interpolate along columns for this row
                rv = 0.0
                for dj in range(4):
                    cj = c0 - 1 + dj
                    cjc = cj
                    if cjc < 0:
                        cjc = 0
                    elif cjc >= sw:
                        cjc = sw - 1
                    sv = src[ric, cjc]
                    if sv != sv:  # NaN check
                        has_nan = True
                        break
                    if dj == 0:
                        rv = sv * wc0
                    elif dj == 1:
                        rv += sv * wc1
                    elif dj == 2:
                        rv += sv * wc2
                    else:
                        rv += sv * wc3
                if has_nan:
                    break
                if di == 0:
                    val = rv * wr0
                elif di == 1:
                    val += rv * wr1
                elif di == 2:
                    val += rv * wr2
                else:
                    val += rv * wr3

            if not has_nan:
                out[i, j] = val
            else:
                # Fall back to bilinear with weight renormalization
                r1 = r0 + 1
                c1 = c0 + 1
                dr = r - r0
                dc = c - c0

                w00 = (1.0 - dr) * (1.0 - dc)
                w01 = (1.0 - dr) * dc
                w10 = dr * (1.0 - dc)
                w11 = dr * dc

                accum = 0.0
                wsum = 0.0

                if 0 <= r0 < sh and 0 <= c0 < sw:
                    v = src[r0, c0]
                    if v == v:
                        accum += w00 * v
                        wsum += w00

                if 0 <= r0 < sh and 0 <= c1 < sw:
                    v = src[r0, c1]
                    if v == v:
                        accum += w01 * v
                        wsum += w01

                if 0 <= r1 < sh and 0 <= c0 < sw:
                    v = src[r1, c0]
                    if v == v:
                        accum += w10 * v
                        wsum += w10

                if 0 <= r1 < sh and 0 <= c1 < sw:
                    v = src[r1, c1]
                    if v == v:
                        accum += w11 * v
                        wsum += w11

                if wsum > 1e-10:
                    out[i, j] = accum / wsum
                else:
                    out[i, j] = nodata
    return out


